import os,re
mods={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn); mods[p[:-5].replace('/','.')]=p
imp={}; ownM={}; bare=set()
for n,p in mods.items():
    ds=[]; own=False
    for line in open(p,errors='replace'):
        m=re.match(r'^import\s+([A-Za-z0-9_.]+)\s*$',line)
        if m:
            d=m.group(1)
            if d=='Mathlib': bare.add(n); own=True
            elif d.startswith('Mathlib.'): own=True
            elif d.startswith('AlgebraicJacobian'): ds.append(d)
    imp[n]=ds; ownM[n]=own
memo={}
def hasbare(m):
    if m in memo: return memo[m]
    memo[m]=False
    r = m in bare or any(hasbare(d) for d in imp.get(m,[]))
    memo[m]=r; return r
risk=[m for m in mods if not ownM[m] and not hasbare(m)]
print(len(risk),'modules have NO Mathlib import and no umbrella anywhere in their closure:')
for r in sorted(risk): print('  ',mods[r])
