import glob,re,collections
def strip_comments(t):
    out=[]
    for line in t.split('\n'):
        i=0; res=''
        while i < len(line):
            if line[i]=='%' and (i==0 or line[i-1]!='\\'): break
            res+=line[i]; i+=1
        out.append(res)
    return '\n'.join(out)
bad=0
for f in sorted(glob.glob('*.tex')):
    t=strip_comments(open(f,encoding='utf-8').read())
    b=collections.Counter(re.findall(r'\\begin\{([a-zA-Z*]+)\}',t))
    e=collections.Counter(re.findall(r'\\end\{([a-zA-Z*]+)\}',t))
    diff={k:b[k]-e[k] for k in set(b)|set(e) if b[k]!=e[k]}
    if diff: print(' UNBALANCED',f,diff); bad+=1
print('chapters:',len(glob.glob('*.tex')),' unbalanced (comments excluded):',bad)
